namespace qpx::detail::reduction {
J parameters(const ExpressionReductionOptions& o){return {{"features",o.features},{"normalization",o.normalization_recipe},{"center",o.center},{"components",o.components},{"oversampling",o.oversampling},{"power_iterations",o.power_iterations},{"clusters",o.clusters},{"max_iterations",o.max_iterations},{"seed",o.seed},{"cluster_tolerance",o.cluster_tolerance}};}
ExpressionReductionOptions parameters(const J& j){
    if(!j.is_object() || j.size()!=10 || !j.at("features").is_array() || j.at("features").size()>1000000 || !j.at("center").is_boolean() || !j.at("cluster_tolerance").is_number_float())throw std::invalid_argument("Invalid reduction parameter schema");ExpressionReductionOptions o;
    for(const auto& f:j.at("features"))o.features.push_back(integer(f,999999));o.normalization_recipe=j.at("normalization").get<std::string>();o.center=j.at("center").get<bool>();o.components=std::uint32_t(integer(j.at("components"),32));o.oversampling=std::uint32_t(integer(j.at("oversampling"),32));o.power_iterations=std::uint32_t(integer(j.at("power_iterations"),4));o.clusters=std::uint32_t(integer(j.at("clusters"),32));o.max_iterations=std::uint32_t(integer(j.at("max_iterations"),1000));o.seed=integer(j.at("seed"),UINT64_MAX);o.cluster_tolerance=j.at("cluster_tolerance").get<double>();if(parameters(o)!=j)throw std::invalid_argument("Noncanonical reduction parameters");return o;
}
void require_parent(const ExpressionReductionResult& r,const ExpressionMatrixSource& source,std::size_t work,const std::atomic<bool>* cancelled){
    work_limit(work);workflow_checkpoint(cancelled);if(r.source_sha256()!=source.metadata().source_sha256 || r.file_sha256()!=source.file_sha256() || r.source_features()!=source.metadata().features || r.observation_ids().size()!=source.metadata().observations)throw WorkflowInputChanged("Reduction parent source differs");std::size_t fixed=r.payload_bytes();workflow_capture_charge(fixed,source.payload_bytes()+4096,work);if(work-fixed<4u*1024*1024)throw WorkflowCaptureLimit("Reduction parent verification leaves no catalogue workspace");const auto remaining=work-fixed;
    for(std::size_t i=0;i<r.features().size();){workflow_checkpoint(cancelled);std::size_t count=1;while(count<128 && i+count<r.features().size() && r.features()[i+count]==r.features()[i]+count)++count;const auto page=source.feature_page(r.features()[i],count,remaining,cancelled);if(page.size()!=count)throw WorkflowInputChanged("Reduction parent feature catalogue truncated");for(std::size_t j=0;j<count;++j)if(page[j].index!=r.features()[i+j] || page[j].id!=r.feature_ids()[i+j])throw WorkflowInputChanged("Reduction feature association differs");i+=count;}
    for(std::size_t first=0;first<r.observation_ids().size();first+=512){const auto count=std::min<std::size_t>(512,r.observation_ids().size()-first);const auto page=source.observation_page(first,count,remaining,cancelled);if(page.size()!=count || !std::equal(page.begin(),page.end(),r.observation_ids().begin()+first))throw WorkflowInputChanged("Reduction observation association differs");}source.require_current(cancelled);
}
}
