std::size_t ExpressionReductionResult::payload_bytes()const{std::size_t n=sizeof(*this)+sizeof(Data)+(data_->features.capacity()+data_->options.features.capacity())*8+data_->labels.capacity()*4+data_->options.normalization_recipe.capacity();for(const auto* s:{&data_->source,&data_->file,&data_->value_source,&data_->domain,&data_->backend,&data_->id})n+=s->capacity();for(const auto* a:{&data_->means,&data_->embedding,&data_->loadings,&data_->singular,&data_->energy,&data_->centres})n+=a->capacity()*8;for(const auto* a:{&data_->feature_ids,&data_->observations}){n+=a->capacity()*sizeof(std::string);for(const auto& s:*a)n+=s.capacity();}return n;}
